catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return;
    }

    var ga = new GlideAjax('x_hccc_hoc_ohs.HoCOHSMFluClinicAjax');

    ga.addParam('sysparm_name', 'alreadyHaveAppointmentExternal');
    ga.addParam('sysparm_email', g_form.getValue('email_address'));
    ga.getXML(function(response) {
        var answer = response.responseXML.documentElement.getAttribute('answer');

        g_form.setValue('already_have_an_active_appointment', "");
        g_form.setValue('already_have_an_active_appointment', answer);
    });

}
